mapper.select:
select

from ad_advertiser_daily
where stat_date = #{statDate}
and advertiser_id = #{advertiserId}

mapper.update:
update ad_advertiser_daily
set charge_cents = charge_cents + #{amountCents}
where stat_date = #{statDate}
and advertiser_id = #{advertiserId}
and (daily_limit_cents = 0 or charge_cents + #{amountCents} <= daily_limit_cents)

update ad_advertiser_daily
set charge_cents = charge_cents - #{amountCents}
where stat_date = #{statDate}
and advertiser_id = #{advertiserId}
and charge_cents >= #{amountCents}

update ad_advertiser_daily
set daily_limit_cents = #{dailyLimitCents}
where stat_date = #{statDate}
and advertiser_id = #{advertiserId}

update ad_advertiser_daily
set charge_cents = #{chargeCents}
where stat_date = #{statDate}
and advertiser_id = #{advertiserId}
